export const aggClusters = (() => {
  const list = [];
  function walk(n) {
    if ('id' in n) list.push({ id: n.id, cx: n.cx, cy: n.cy, kwcount: n.kwcount, kw0: n.kw0 });
    else if (n.children) n.children.forEach(walk);
  }
  walk(TREE);
  return list.sort((a, b) => a.id - b.id);
})();

